                                  '\n'
                                  '\n'
                                  'def _club_bind_historical_parse_class(case):\n'
                                  '    from functools import wraps\n'
                                  '    for name, original in tuple(vars(case).items()):\n'
                                  "        if name.startswith('test_') and callable(original):\n"
                                  '            def bind(function):\n'
                                  '                @wraps(function)\n'
                                  '                def checked(*args, **kwargs):\n'
                                  '                    with _club_history.club_authenticated_transaction():\n'
                                  '                        _CLUB_PARSE_HISTORY.verify()\n'
                                  '                        try:\n'
                                  '                            return function(*args, **kwargs)\n'
                                  '                        finally:\n'
                                  '                            _CLUB_PARSE_HISTORY.verify()\n'
                                  '                return checked\n'
                                  '            setattr(case, name, bind(original))\n'
                                  '    return case\n'
                                  '\n'
                                  '\n'
                                  'ReadinessParseCacheSourceChainTests = '
                                  '_club_bind_historical_parse_class(_CLUB_PARSE_TESTS.ReadinessParseCacheSourceChainTests)\n'
